// Fort Bragg Local works without the internet.
//
// This service worker keeps a copy of the whole site on the visitor's device: the page, styles,
// scripts, fonts, icons, every listing and the printable list (about 1 MB). It always asks the
// network first, so visitors see the newest listings whenever they're online, and falls back to the
// saved copy when they're offline or the connection is too slow to answer within a few seconds.
// Map tiles and other websites are never stored, so the map needs the internet.

// BEGIN GENERATED by tools/build-offline.mjs (don't edit by hand)
const VERSION = '4bd1a0d11f63';
const CORE = [
  './',
  'directory.html',
  '404.html',
  'site.webmanifest',
  'assets/css/app.css',
  'assets/js/app.js',
  'assets/js/config.js',
  'assets/js/hours.js',
  'assets/js/intents.js',
  'assets/js/map.js',
  'assets/js/offline.js',
  'assets/js/search.js',
  'assets/js/sky.js',
  'assets/js/taxonomy.js',
  'assets/fonts/atkinson-hyperlegible-next-latin-ext-wght-normal.woff2',
  'assets/fonts/atkinson-hyperlegible-next-latin-wght-italic.woff2',
  'assets/fonts/atkinson-hyperlegible-next-latin-wght-normal.woff2',
  'assets/fonts/fraunces-latin-ext-opsz-normal.woff2',
  'assets/fonts/fraunces-latin-opsz-italic.woff2',
  'assets/fonts/fraunces-latin-opsz-normal.woff2',
  'assets/img/favicon.svg',
  'assets/img/apple-touch-icon.png',
  'assets/img/icon-192.png',
  'data/businesses.json'
];
// END GENERATED

const PREFIX = 'fortbragg-local-';
const CACHE = PREFIX + VERSION;
const SCOPE = new URL(self.registration.scope);
const SHELL = new URL('./', SCOPE).href; // the app page, whatever its ?query
const NOT_FOUND = new URL('404.html', SCOPE).href;
const CORE_URLS = new Set(CORE.map(p => new URL(p, SCOPE).href));
const WAIT_MS = { page: 4000, data: 4000, other: 6000 };

// Save every file first. If one can't be saved, this version doesn't install and the browser tries
// again on the next visit, so a half-saved copy is never used.
self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    try {
      await Promise.all([...CORE_URLS].map(async url => {
        const res = await fetch(url, { cache: 'reload' }); // straight from the server, never a stale browser copy
        if (!res.ok) throw new Error(`could not save ${url} (${res.status})`);
        await cache.put(url, await withoutRedirect(res));
      }));
    } catch (err) {
      await caches.delete(CACHE); // never leave a half-saved copy behind
      throw err;
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key.startsWith(PREFIX) && key !== CACHE) await caches.delete(key);
    await self.clients.claim();
    for (const client of await self.clients.matchAll({ type: 'window' })) client.postMessage(await status());
  })());
});

self.addEventListener('message', event => {
  if (event.data && event.data.type === 'status') event.waitUntil(status().then(s => event.source && event.source.postMessage(s)));
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET' || req.headers.has('range')) return;
  const url = new URL(req.url);
  // Only this site's own files. Map tiles, other websites and other projects on the same host go
  // straight to the network as usual.
  if (url.origin !== SCOPE.origin || !url.pathname.startsWith(SCOPE.pathname)) return;
  event.respondWith(respond(event, req, url));
});

async function respond(event, req, url) {
  const page = req.mode === 'navigate';
  const key = page && (url.pathname === SCOPE.pathname || url.pathname === SCOPE.pathname + 'index.html')
    ? SHELL
    : url.origin + url.pathname; // ignore query strings
  const kind = page ? 'page' : /\.json$/.test(url.pathname) ? 'data' : 'other';
  const cache = await caches.open(CACHE);

  const network = fetch(req).then(async res => {
    // Keep the saved copy fresh with good answers for our own files (never error pages or redirects).
    const keep = res.ok && res.type === 'basic' && !res.redirected && (!page || CORE_URLS.has(key));
    if (keep) await cache.put(key, res.clone());
    return res;
  });
  event.waitUntil(network.then(() => {}, () => {})); // let a slow download finish and refresh the copy

  try {
    const res = await within(network, WAIT_MS[kind]);
    // A passing server hiccup (an error or "too many requests") shouldn't hide a good saved copy.
    if (res.status >= 500 || res.status === 429) { const saved = await cache.match(key); if (saved) return saved; }
    return res;
  } catch {
    // Offline or too slow: use the saved copy.
    const saved = (await cache.match(key)) || (page ? await cache.match(NOT_FOUND) : undefined);
    return saved || network;
  }
}

async function status() {
  const cache = await caches.open(CACHE);
  const keys = new Set((await cache.keys()).map(r => r.url));
  return { type: 'offline-status', version: VERSION, ready: [...CORE_URLS].every(u => keys.has(u)) };
}

function within(promise, ms) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error('timeout')), ms);
    promise.then(v => { clearTimeout(t); resolve(v); }, e => { clearTimeout(t); reject(e); });
  });
}

// Safari won't show a saved page that came from a redirect, so store a plain copy.
async function withoutRedirect(res) {
  if (!res.redirected) return res;
  return new Response(await res.blob(), { status: res.status, statusText: res.statusText, headers: res.headers });
}
